 hist=[{'kernel':r['kernel'],'active_thread_instructions':r['active_thread_instructions'],'complete_ctas':r['complete_ctas'],'memory_instruction_paths':r['memory_instruction_paths'],'global_reference_histogram':r['global_reference_histogram'],'opcodes':r['opcodes']}for r in br['qualification']['rows']]
